// FUNCTION: BFME2 0x0045880B size=54 name=?getBridgeTowerBehaviorInterfaceFromObject@BridgeTowerBehavior@@SAPAVBridgeTowerBehaviorInterface@@PAVObject@@@Z evidence=N:ledger
BridgeTowerBehaviorInterface *BridgeTowerBehavior::getBridgeTowerBehaviorInterfaceFromObject(Object *obj)
{
	if (obj != NULL && obj->getTemplate()->isKindOf(KINDOF_BRIDGE_TOWER))
	{
		for (BehaviorModule **module = obj->getBehaviorModules(); *module != NULL; ++module)
		{
			BridgeTowerBehaviorInterface *towerInterface = (*module)->getBridgeTowerBehaviorInterface();
			if (towerInterface != NULL)
				return towerInterface;
		}
	}
	return NULL;
}

// A hit on one tower is shared with the bridge and the other three towers, unless the hit
// came from the bridge or a tower. Each gets the same fraction of its own maximum health.
// FUNCTION: BFME2 0x00458841 size=342 name=?onDamage@BridgeTowerBehavior@@UAEXPAVDamageInfo@@@Z evidence=N:ledger
void BridgeTowerBehavior::onDamage(DamageInfo *blow)
{
	Object *bridge = TheGameLogic->findObjectByID(getBridgeID());
	if (bridge == NULL)
		return;

	Real shareOfMax = blow->in.m_amount / getObject()->getBodyModule()->getMaxHealth();

	BridgeBehaviorInterface *spanInterface = NULL;
	for (BehaviorModule **module = bridge->getBehaviorModules(); *module != NULL; ++module)
	{
		spanInterface = (*module)->getBridgeBehaviorInterface();
		if (spanInterface != NULL)
			break;
	}
	if (spanInterface == NULL)
		return;

	Object *source = TheGameLogic->findObjectByID(blow->in.m_sourceID);
	if (source != NULL && (source->getTemplate()->m_kindof.m_bits[0] & ((1u << KINDOF_BRIDGE) | (1u << KINDOF_BRIDGE_TOWER))) != 0)
		return;

	for (Int slot = 0; slot < BRIDGE_MAX_TOWERS; ++slot)
	{
		Object *tower = TheGameLogic->findObjectByID(spanInterface->getTowerID((BridgeTowerType)slot));
		if (tower != NULL && tower != getObject())
		{
			BodyModuleInterface *towerHealthSource = tower->getBodyModule();
			DamageInfo towerHit;
			towerHit.in.m_amount = towerHealthSource->getMaxHealth() * shareOfMax;
			towerHit.in.m_sourceID = getObject()->getID();
			towerHit.in.m_damageType = blow->in.m_damageType;
			towerHit.in.m_deathType = blow->in.m_deathType;
			tower->attemptDamage(&towerHit);
		}
	}

	BodyModuleInterface *bridgeHealthSource = bridge->getBodyModule();
	DamageInfo bridgeHit;
	bridgeHit.in.m_amount = bridgeHealthSource->getMaxHealth() * shareOfMax;
	bridgeHit.in.m_sourceID = getObject()->getID();
	bridgeHit.in.m_damageType = blow->in.m_damageType;
	bridgeHit.in.m_deathType = blow->in.m_deathType;
	bridge->attemptDamage(&bridgeHit);
}

// FUNCTION: BFME2 0x00458997 size=241 name=?onHealing@BridgeTowerBehavior@@UAEXPAVDamageInfo@@@Z evidence=N:ledger
void BridgeTowerBehavior::onHealing(DamageInfo *blow)
{
	Object *bridge = TheGameLogic->findObjectByID(getBridgeID());
	if (bridge == NULL)
		return;

	Real shareOfMax = blow->in.m_amount / getObject()->getBodyModule()->getMaxHealth();

	BridgeBehaviorInterface *spanInterface = NULL;
	for (BehaviorModule **module = bridge->getBehaviorModules(); *module != NULL; ++module)
	{
		spanInterface = (*module)->getBridgeBehaviorInterface();
		if (spanInterface != NULL)
			break;
	}
	if (spanInterface == NULL)
		return;

	Object *source = TheGameLogic->findObjectByID(blow->in.m_sourceID);
	if (source != NULL && (source->getTemplate()->m_kindof.m_bits[0] & ((1u << KINDOF_BRIDGE) | (1u << KINDOF_BRIDGE_TOWER))) != 0)
		return;

	for (Int slot = 0; slot < BRIDGE_MAX_TOWERS; ++slot)
	{
		Object *tower = TheGameLogic->findObjectByID(spanInterface->getTowerID((BridgeTowerType)slot));
		if (tower != NULL && tower != getObject())
			tower->attemptHealing(tower->getBodyModule()->getMaxHealth() * shareOfMax, getObject());
	}

	bridge->attemptHealing(bridge->getBodyModule()->getMaxHealth() * shareOfMax, getObject());
}

// FUNCTION: BFME2 0x00458A88 size=38 name=?onDie@BridgeTowerBehavior@@UAEXPBVDamageInfo@@@Z evidence=N:ledger
void BridgeTowerBehavior::onDie(const DamageInfo *damageInfo)
{
	Object *bridge = TheGameLogic->findObjectByID(getBridgeID());
	if (bridge != NULL)
		bridge->kill(DAMAGE_UNRESISTABLE, DEATH_NORMAL);
}

